import importlib

mods = ["pypdf", "PyPDF2", "fitz", "reportlab", "pdfplumber", "pikepdf"]
for m in mods:
    try:
        mod = importlib.import_module(m)
        print(m, "OK", getattr(mod, "__version__", ""))
    except Exception as e:
        print(m, "MISSING", type(e).__name__)

import re

with open("report.pdf", "rb") as f:
    data = f.read()

# parse xref
m = re.search(rb"startxref\s+(\d+)", data)
xref_off = int(m.group(1))
i = xref_off + 4
entries = {}
while True:
    while i < len(data) and data[i:i + 1] in (b"\n", b"\r", b" "):
        i += 1
    line = data[i:i + 40].split(b"\r\n")[0].split(b"\n")[0].split(b"\r")[0].strip()
    if line.startswith(b"trailer"):
        break
    start, count = int(line.split()[0]), int(line.split()[1])
    i = data.find(b"\n", i) + 1
    for k in range(count):
        ent = data[i:i + 20]
        entries[start + k] = (int(ent[0:10]), int(ent[11:16]), chr(ent[17]))
        i += 20
    while i < len(data) and data[i:i + 1] in (b"\n", b"\r"):
        i += 1

inuse = {k: v for k, v in entries.items() if v[2] == "n"}
offs = sorted(inuse.items(), key=lambda kv: kv[1][0])
for j, (objnum, (off, gen, typ)) in enumerate(offs):
    end = offs[j + 1][1][0] if j + 1 < len(offs) else len(data)
    print(f"----- object {objnum} (offset {off}, raw slice {off}:{end}) -----")
    print(data[off:end].decode("latin-1"))
    print()

